from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI()

class ItemMasuk(BaseModel):
    nama: str = Field(min_length=1)
    harga: float = Field(gt=0)

DB: dict[int, dict] = {}
N = 0

@app.post('/item', status_code=201)
def cipta(item: ItemMasuk):
    global N
    N += 1
    DB[N] = item.model_dump() | {'id': N}
    return DB[N]

@app.get('/item/{id}')
def baca(id: int):
    if id not in DB:
        raise HTTPException(404, 'tiada')
    return DB[id]
```
